// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import {
  BrowserChrome,
  DemoStage,
  DockHeader,
  Label,
  MockPage,
  mockImage,
  type Build,
} from '@/app/demos/stage'
import { CameraIcon, FrameIcon, MousePointerClickIcon, UnfoldVerticalIcon } from 'lucide-react'

import { CAPTIONS, MODES } from './script'

const MODE_ICONS = {
  entire: UnfoldVerticalIcon,
  visible: CameraIcon,
  selection: FrameIcon,
  element: MousePointerClickIcon,
} as const

const SHOT = { x: 14, y: 96, w: 290, h: 150 }

const build: Build = ({ tl, q, step, final, move, moveTo, click, count, wait, cursorOut, pos }) => {
  const page = pos('page', 0, 0)
  step(0)
  move('mode-selection', { at: 0.3 })
  click('mode-selection')
  tl.to(
    q('mode-selection'),
    {
      backgroundColor: 'rgba(192,132,252,0.18)',
      borderColor: 'rgba(192,132,252,0.6)',
      duration: 0.2,
    },
    '<',
  )
  moveTo(page.x + SHOT.x, page.y + SHOT.y)
  tl.to([q('marquee'), q('size')], { opacity: 1, duration: 0.2 })
  moveTo(page.x + SHOT.x + SHOT.w, page.y + SHOT.y + SHOT.h, { duration: 1.1 })
  tl.to(q('marquee'), { width: SHOT.w, height: SHOT.h, duration: 1.1, ease: 'power3.inOut' }, '<')
  count('size-w', SHOT.w, { at: '<', duration: 1.1, ease: 'power3.inOut' })
  count('size-h', SHOT.h, { at: '<', duration: 1.1, ease: 'power3.inOut' })

  step(1, '+=0.3')
  tl.fromTo(q('flash'), { opacity: 0 }, { opacity: 0.9, duration: 0.08, ease: 'none' })
  tl.to(q('flash'), { opacity: 0, duration: 0.5, ease: 'power2.out' })
  tl.to(
    q('marquee'),
    { boxShadow: '0 0 0 9999px rgba(0,0,0,0)', borderStyle: 'solid', scale: 1.04, duration: 0.6 },
    '<',
  )
  tl.to(q('size'), { opacity: 0, duration: 0.2 }, '<')
  cursorOut('<')

  step(2, '+=0.3')
  tl.fromTo(q('arrow'), { drawSVG: '0%' }, { drawSVG: '100%', duration: 0.8, ease: 'power2.inOut' })
  tl.fromTo(
    q('ring'),
    { drawSVG: '0%' },
    { drawSVG: '100%', duration: 0.7, ease: 'power2.inOut' },
    '-=0.3',
  )
  tl.to(q('blur'), { opacity: 1, scaleX: 1, duration: 0.6 }, '-=0.2')

  step(3, '+=0.6')
  const slot = pos('history-slot', 0, 0)
  const origin = pos('marquee', 0, 0)
  tl.to(q('marquee'), {
    x: slot.x - origin.x,
    y: slot.y - origin.y,
    scale: q('history-slot').offsetWidth / SHOT.w,
    transformOrigin: '0% 0%',
    duration: 1,
    ease: 'expo.inOut',
  })
  tl.to(q('history-badge'), { opacity: 1, scale: 1, duration: 0.4, ease: 'back.out(3)' }, '-=0.2')
  final()
  wait(1.6)
  tl.to([q('marquee'), q('history-badge')], { opacity: 0, duration: 0.4 })
}

export default function Demo() {
  return (
    <DemoStage
      label="Capture Toolkit selecting part of a page, annotating it, blurring an email and saving it to history"
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome
        url="https://northwind.app/launch"
        panelWidth={180}
        panel={
          <div className="flex h-full flex-col">
            <DockHeader />
            <div className="space-y-1.5 p-2.5">
              {MODES.slice(0, 4).map(({ id, label }) => {
                const Icon = MODE_ICONS[id as keyof typeof MODE_ICONS]
                const d = id === 'selection' ? 'mode-selection' : `mode-${id}`
                return (
                  <div
                    key={id}
                    data-d={d}
                    className="flex items-center gap-2 rounded-lg border border-line bg-canvas/60 px-2.5 py-2 text-[11px] text-ink-soft"
                  >
                    <Icon className="size-3.5 text-[var(--accent)]" />
                    {label}
                  </div>
                )
              })}
            </div>
            <div className="mt-auto p-2.5">
              <Label>History</Label>
              <div className="mt-2 grid grid-cols-2 gap-1.5">
                <span
                  className="h-11 rounded-md"
                  style={{ background: mockImage(2), opacity: 0.6 }}
                />
                <span
                  className="h-11 rounded-md"
                  style={{ background: mockImage(4), opacity: 0.6 }}
                />
                <span
                  data-d="history-slot"
                  className="relative h-11 rounded-md border border-dashed border-line-strong"
                >
                  <span
                    data-d="history-badge"
                    className="absolute -right-1 -top-1 z-10 flex size-4 scale-0 items-center justify-center rounded-full bg-[var(--accent)] text-[8px] font-bold text-canvas opacity-0"
                  >
                    1
                  </span>
                </span>
              </div>
            </div>
          </div>
        }
      >
        <div data-d="page" className="relative h-full">
          <MockPage variant="landing" />
          <div
            data-d="marquee"
            className="absolute z-20 overflow-hidden rounded-sm border-2 border-dashed border-[var(--accent)] opacity-0"
            style={{
              left: SHOT.x,
              top: SHOT.y,
              width: 0,
              height: 0,
              boxShadow: '0 0 0 9999px rgba(0,0,0,0.55)',
            }}
          >
            <svg
              viewBox={`0 0 ${SHOT.w} ${SHOT.h}`}
              className="absolute left-0 top-0"
              style={{ width: SHOT.w, height: SHOT.h }}
            >
              <path
                data-d="arrow"
                d="M240 30 C 200 20, 170 40, 150 70 M150 70 l4 -14 M150 70 l14 -4"
                fill="none"
                stroke="#fb7185"
                strokeWidth="3"
                strokeLinecap="round"
              />
              <ellipse
                data-d="ring"
                cx="100"
                cy="64"
                rx="70"
                ry="22"
                fill="none"
                stroke="#fb7185"
                strokeWidth="2.5"
              />
            </svg>
            <span
              data-d="blur"
              className="absolute left-[18px] top-[52px] h-4 w-36 origin-left scale-x-0 rounded bg-white/50 opacity-0 backdrop-blur-md"
            />
          </div>
          <span
            data-d="size"
            className="absolute z-30 rounded opacity-0 bg-[var(--accent)] px-1.5 py-0.5 font-mono text-[9px] text-canvas"
            style={{ left: SHOT.x + 4, top: SHOT.y - 18 }}
          >
            <span data-d="size-w">0</span> × <span data-d="size-h">0</span>
          </span>
          <div
            data-d="flash"
            className="pointer-events-none absolute inset-0 z-40 bg-white opacity-0"
          />
        </div>
      </BrowserChrome>
    </DemoStage>
  )
}
